-- PostgreSQL. Load the CSV generated by src/prepare_data.py into this table.
-- source_row is the original worksheet row, including the header offset.
CREATE SCHEMA IF NOT EXISTS retail;

CREATE TABLE IF NOT EXISTS retail.invoice_lines (
    source_row BIGINT PRIMARY KEY,
    invoice_no TEXT NOT NULL,
    stock_code TEXT NOT NULL,
    description TEXT,
    quantity BIGINT NOT NULL,
    invoice_date TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    unit_price NUMERIC NOT NULL,
    customer_id TEXT,
    country TEXT NOT NULL,
    is_duplicate BOOLEAN NOT NULL,
    is_cancellation BOOLEAN NOT NULL,
    has_customer_id BOOLEAN NOT NULL,
    eligible_sale BOOLEAN NOT NULL,
    eligible_cancellation BOOLEAN NOT NULL
);

-- Use positive-price, positive-quantity non-cancelled records for sales.
-- Missing customer IDs remain available for sales reporting.
CREATE OR REPLACE VIEW retail.sales_lines AS
SELECT *, quantity * unit_price AS sales_value_gbp
FROM retail.invoice_lines
WHERE eligible_sale;

CREATE OR REPLACE VIEW retail.cancellation_lines AS
SELECT *, -quantity * unit_price AS cancellation_value_gbp
FROM retail.invoice_lines
WHERE eligible_cancellation;

-- One invoice is one observed order. No assumed timezone conversion.
CREATE OR REPLACE VIEW retail.customer_orders AS
SELECT invoice_no, customer_id, MIN(invoice_date) AS order_date,
       SUM(sales_value_gbp) AS sales_value_gbp
FROM retail.sales_lines
WHERE has_customer_id
GROUP BY invoice_no, customer_id;
